// 1. The price list from the sheet, by keyword: base, bedroom, deep, oven...
const price = {};
for (const row of $input.all()) price[row.json.keyword] = Number(row.json.price);

// 2. The customer's answers from the form
const form = $('Quote Request').first().json;
const beds = Number(form['Bedrooms']) || 0;
const baths = Number(form['Bathrooms']) || 0;
const asked = String(form['Anything extra?'] || '').toLowerCase();

// 3. Add it up, line by line
const lines = [
  ['Base visit', price.base],
  [`${beds} bedroom${beds === 1 ? '' : 's'}`, beds * price.bedroom],
  [`${baths} bathroom${baths === 1 ? '' : 's'}`, baths * price.bathroom],
];
const fixed = ['base', 'bedroom', 'bathroom', 'minimum'];
for (const { json: row } of $input.all()) {
  if (!fixed.includes(row.keyword) && asked.includes(row.keyword)) lines.push([row.item, Number(row.price)]);
}
const sum = lines.reduce((total, [, amount]) => total + amount, 0);
const extras = lines.slice(3).map(([item]) => item).join(', ') || 'none';

// 4. Never below the minimum charge
const total = Math.max(sum, price.minimum);
if (total > sum) lines.push(['Minimum charge top-up', total - sum]);

return [{ json: {
  quote: 'Q-' + $now.toFormat('MMdd-HHmm'),
  name: form['Your name'],
  email: form['Email'],
  beds, baths,
  extras,
  breakdown: lines.map(([item, amount]) => `${item}: $${amount}`).join('\n'),
  total,
  price: '$' + total,
  valid_until: $now.plus({ days: 14 }).toFormat('d LLLL'),
  received: $now.toFormat('yyyy-MM-dd HH:mm'),
} }];

